@app.cell(hide_code=True)
def governance_core():
    """Stable wire identities and immutable byte/ledger records."""
    import hashlib
    import json
    from dataclasses import dataclass

    GENESIS_HASH = "0" * 64

    def canonical_json(value):
        return json.dumps(
            value,
            sort_keys=True,
            separators=(",", ":"),
            ensure_ascii=False,
        )

    def sha256_text(payload):
        return hashlib.sha256(
            payload.encode("utf-8")
        ).hexdigest()

    class GovernanceError(RuntimeError):
        pass

    class QuarantineError(GovernanceError):
        pass

    class HoldError(GovernanceError):
        pass

    @dataclass(frozen=True, slots=True)
    class Chunk:
        index: int
        start: int
        end: int
        data: bytes
        fingerprint: int
        reason: str

    @dataclass(frozen=True, slots=True)
    class Transaction:
        session_id: str
        sequence_number: int
        source_agent: str
        target_entity: str
        payload: str
        previous_hash: str
        expected_hash: str | None = None

    @dataclass(frozen=True, slots=True)
    class LedgerRecord:
        session_id: str
        sequence_number: int
        source_agent: str
        target_entity: str
        payload_hash: str
        previous_hash: str
        block_hash: str
        timestamp_ns: int
        verified: bool = True

    def block_material(tx, payload_hash):
        # Exclude the nondeterministic receipt timestamp and optional assertion.
        return dict(
            version=1,
            session_id=tx.session_id,
            sequence_number=tx.sequence_number,
            source_agent=tx.source_agent,
            target_entity=tx.target_entity,
            payload_hash=payload_hash,
            previous_hash=tx.previous_hash,
        )

    """Packet-independent polynomial CDC with one modular reduction per byte."""
    from collections import deque

    class RabinCDCScanner:
        """Polynomial rolling CDC (Rabin–Karp style, not a GF(2) Rabin fingerprint).

        Hash the last W bytes in base 256 modulo 2**61-1. A separate boundary
        modulus controls cuts. feed() yields chunks independent of packetization;
        finish() emits the tail. Chunks remain bytes, even across UTF-8 characters.
        The rolling window continues across cuts, helping content resynchronize.
        """

        def __init__(
            self,
            block_size_target=512,
            window_size=64,
            min_size=None,
            max_size=None,
            target=1,
        ):
            if (
                type(block_size_target) is not int
                or block_size_target < 2
            ):
                raise ValueError(
                    "block_size_target must be an integer >= 2"
                )
            if (
                type(window_size) is not int
                or window_size < 1
            ):
                raise ValueError(
                    "window_size must be a positive integer"
                )
            self.modulus = block_size_target
            self.window_size = window_size
            self.min_size = (
                max(window_size, block_size_target // 4)
                if min_size is None
                else min_size
            )
            self.max_size = (
                block_size_target * 4
                if max_size is None
                else max_size
            )
            if not (
                type(self.min_size) is int
                and type(self.max_size) is int
                and window_size
                <= self.min_size
                <= self.max_size
            ):
                raise ValueError(
                    "Require window_size <= min_size <= max_size"
                )
            if (
                type(target) is not int
                or not 0 <= target < self.modulus
            ):
                raise ValueError(
                    "target must be inside the boundary modulus"
                )
            self.target = target
            self.base = 256
            self.field_prime = (1 << 61) - 1
            self._remove_factor = pow(
                self.base, window_size - 1, self.field_prime
            )
            removal = (
                self._remove_factor
                * self.base
                % self.field_prime
            )
            self._remove_table = tuple(
                byte * removal % self.field_prime
                for byte in range(256)
            )
            self._boundary_mask = (
                self.modulus - 1
                if self.modulus & (self.modulus - 1) == 0
                else None
            )
            self._window = deque()
            self._buffer = bytearray()
            self._fingerprint = 0
            self._offset = 0
            self._chunk_start = 0
            self._index = 0
            self._finished = False

        def _cut(self, reason):
            chunk = Chunk(
                self._index,
                self._chunk_start,
                self._offset,
                bytes(self._buffer),
                self._fingerprint,
                reason,
            )
            self._buffer.clear()
            self._chunk_start = self._offset
            self._index += 1
            return chunk

        def feed(self, data):
            if self._finished:
                raise RuntimeError(
                    "Cannot feed after finish()"
                )
            if not isinstance(
                data, (bytes, bytearray, memoryview)
            ):
                raise TypeError(
                    "feed() requires bytes; encode text once at the boundary"
                )
            view = memoryview(data).cast("B")
            window, buffer = self._window, self._buffer
            append, pop = window.append, window.popleft
            fingerprint, offset = (
                self._fingerprint,
                self._offset,
            )
            size, segment, processed = len(buffer), 0, 0
            width, prime, remove = (
                self.window_size,
                self.field_prime,
                self._remove_table,
            )
            minimum, maximum = self.min_size, self.max_size
            mask, modulus, target = (
                self._boundary_mask,
                self.modulus,
                self.target,
            )
            try:
                for position, byte in enumerate(view):
                    subtraction = (
                        remove[pop()]
                        if len(window) == width
                        else 0
                    )
                    fingerprint = (
                        (fingerprint << 8)
                        + byte
                        - subtraction
                    ) % prime
                    append(byte)
                    offset += 1
                    size += 1
                    processed = position + 1
                    if size < minimum:
                        continue
                    remainder = (
                        fingerprint & mask
                        if mask is not None
                        else fingerprint % modulus
                    )
                    if (
                        remainder == target
                        or size >= maximum
                    ):
                        buffer.extend(
                            view[segment:processed]
                        )
                        segment, size = processed, 0
                        self._fingerprint, self._offset = (
                            fingerprint,
                            offset,
                        )
                        yield self._cut(
                            "content"
                            if remainder == target
                            else "max size"
                        )
            finally:
                buffer.extend(view[segment:processed])
                self._fingerprint, self._offset = (
                    fingerprint,
                    offset,
                )

        def finish(self):
            if self._finished:
                return []
            self._finished = True
            return (
                [self._cut("tail")] if self._buffer else []
            )

        def chunk_stream(self, text_stream):
            """Convenience API for a fresh scanner; byte offsets are authoritative."""
            return [
                *self.feed(text_stream.encode("utf-8")),
                *self.finish(),
            ]

    """Resource limits, session controls and bounded diagnostic state."""
    import asyncio
    from collections import OrderedDict, deque
    from types import MappingProxyType

    class EngineState:
        def __init__(
            self,
            queue_size=64,
            max_payload_bytes=2_000_000,
            *,
            max_pending_bytes=4_000_000,
            max_records=10_000,
            max_sessions=1024,
            receipt_capacity=1024,
            event_capacity=1024,
            hash_offload_bytes=65536,
            hash_timeout=5.0,
            wait_timeout=10.0,
            shutdown_timeout=5.0,
            yield_every=32,
            transaction_timeout=10.0,
            verification_capacity=8,
            max_verification_bytes=4_000_000,
        ):
            limits = dict(
                queue_size=queue_size,
                max_payload_bytes=max_payload_bytes,
                max_pending_bytes=max_pending_bytes,
                max_records=max_records,
                max_sessions=max_sessions,
                receipt_capacity=receipt_capacity,
                event_capacity=event_capacity,
                yield_every=yield_every,
                verification_capacity=verification_capacity,
                max_verification_bytes=max_verification_bytes,
            )
            for name, value in limits.items():
                if type(value) is not int or value < 1:
                    raise ValueError(
                        f"{name} must be a positive integer"
                    )
                setattr(self, name, value)
            if (
                type(hash_offload_bytes) is not int
                or hash_offload_bytes < 0
            ):
                raise ValueError(
                    "hash_offload_bytes must be a nonnegative integer"
                )
            for name, value in dict(
                hash_timeout=hash_timeout,
                wait_timeout=wait_timeout,
                shutdown_timeout=shutdown_timeout,
                transaction_timeout=transaction_timeout,
            ).items():
                if type(value) not in (
                    int,
                    float,
                ) or not 0 < value < float("inf"):
                    raise ValueError(
                        f"{name} must be finite and positive"
                    )
                setattr(self, name, value)
            self.hash_offload_bytes = hash_offload_bytes
            self.queue = asyncio.Queue(maxsize=queue_size)
            self._ledger, self._heads, self._locks = (
                {},
                {},
                {},
            )
            self._pending, self._completed = (
                {},
                OrderedDict(),
            )
            self._payload_hashes, self._quarantined = (
                set(),
                set(),
            )
            self._held_sessions = {}
            self._events = deque(maxlen=event_capacity)
            self._event_count = self._pending_bytes = 0
            self._inline_jobs = self._thread_jobs = 0
            self._verification_jobs = (
                self._verification_bytes
            ) = 0
            self._worker, self._held_reason = None, None
            self._shutdown_task = None
            self._closed = False

        @property
        def ledger(self):
            return MappingProxyType(self._ledger)

        @property
        def events(self):
            return tuple(
                MappingProxyType(event)
                for event in self._events
            )

        def head(self, session_id):
            return self._heads.get(
                session_id, (-1, GENESIS_HASH)
            )

        def _event(
            self, event, session_id, sequence_number, detail
        ):
            self._events.append(
                dict(
                    order=self._event_count,
                    event=event,
                    session_id=session_id,
                    sequence=sequence_number,
                    detail=detail,
                )
            )
            self._event_count += 1

        def _register_session(self, session_id):
            if session_id not in self._heads:
                if len(self._heads) >= self.max_sessions:
                    raise HoldError("SESSION_CAPACITY")
                self._heads[session_id] = (-1, GENESIS_HASH)

        def session_lock(self, session_id):
            self._register_session(session_id)
            return self._locks.setdefault(
                session_id, asyncio.Lock()
            )

        def quarantine(
            self, session_id, sequence_number, reason
        ):
            try:
                self._register_session(session_id)
            except HoldError:
                return  # No capacity to admit an unknown session either.
            if session_id not in self._quarantined:
                self._quarantined.add(session_id)
                self._event(
                    "SYSTEM_QUARANTINE",
                    session_id,
                    sequence_number,
                    reason,
                )

        def hold_session(self, session_id, reason):
            self._register_session(session_id)
            self._held_sessions[session_id] = reason
            self._event(
                "SESSION_HOLD", session_id, -1, reason
            )

        def _hold(self, reason):
            if self._held_reason is None:
                self._held_reason = reason
                self._event(
                    "ENGINE_HOLD", "engine", -1, reason
                )

        def _check_session(self, session_id):
            if session_id in self._quarantined:
                raise QuarantineError(
                    "Session is quarantined"
                )
            if (
                self._held_reason
                or session_id in self._held_sessions
            ):
                raise HoldError(
                    self._held_reason
                    or self._held_sessions[session_id]
                )

        def health(self):
            alive = (
                self._worker is not None
                and not self._worker.done()
            )
            return dict(
                state="closed"
                if self._closed
                else "held"
                if self._held_reason
                else "running"
                if alive
                else "stopped",
                hold_reason=self._held_reason,
                records=len(self._ledger),
                sessions=len(self._heads),
                pending=len(self._pending),
                pending_bytes=self._pending_bytes,
                queue_depth=self.queue.qsize(),
                receipt_cache=len(self._completed),
                event_cache=len(self._events),
                events_evicted=max(
                    0, self._event_count - len(self._events)
                ),
                quarantined_sessions=len(self._quarantined),
                held_sessions=len(self._held_sessions),
                inline_hash_jobs=self._inline_jobs,
                thread_hash_jobs=self._thread_jobs,
                active_verifications=self._verification_jobs,
                verification_bytes=self._verification_bytes,
                worker_alive=alive,
                limits=dict(
                    max_records=self.max_records,
                    max_sessions=self.max_sessions,
                    receipt_capacity=self.receipt_capacity,
                    event_capacity=self.event_capacity,
                    max_pending_bytes=self.max_pending_bytes,
                    verification_capacity=self.verification_capacity,
                    max_verification_bytes=self.max_verification_bytes,
                ),
            )

    """Bounded queue admission and cancellation-safe per-token completion."""
    import asyncio
    import re
    import uuid

    class ReceiptFlow:
        @staticmethod
        def _valid_hash(value):
            return (
                isinstance(value, str)
                and re.fullmatch(r"[0-9a-f]{64}", value)
                is not None
            )

        def _payload_bytes(self, payload):
            if not isinstance(payload, str):
                raise ValueError("payload must be a string")
            if len(payload) > self.max_payload_bytes:
                raise ValueError(
                    "Payload exceeds configured size limit"
                )
            encoded = payload.encode("utf-8")
            if len(encoded) > self.max_payload_bytes:
                raise ValueError(
                    "Payload exceeds configured size limit"
                )
            return encoded

        def _parse(self, frame):
            tx = Transaction(**frame)
            for field in (
                tx.session_id,
                tx.source_agent,
                tx.target_entity,
            ):
                if (
                    not isinstance(field, str)
                    or not field.strip()
                    or len(field) > 256
                ):
                    raise ValueError(
                        "Identifiers must be nonempty strings <= 256 characters"
                    )
            if (
                type(tx.sequence_number) is not int
                or tx.sequence_number < 0
            ):
                raise ValueError(
                    "sequence_number must be a nonnegative integer"
                )
            if not isinstance(tx.payload, str):
                raise ValueError("payload must be a string")
            if not self._valid_hash(tx.previous_hash):
                raise ValueError(
                    "previous_hash must be 64 lowercase hex characters"
                )
            if (
                tx.expected_hash is not None
                and not self._valid_hash(tx.expected_hash)
            ):
                raise ValueError(
                    "expected_hash must be 64 lowercase hex characters"
                )
            return tx

        async def governance_commit_state(self, **frame):
            if (
                self._closed
                or self._worker is None
                or self._worker.done()
            ):
                raise HoldError(
                    "Start a live engine before submitting"
                )
            try:
                tx = self._parse(frame)
                self._check_session(tx.session_id)
                if self.queue.full():
                    return dict(
                        status="busy",
                        reason="QUEUE_CAPACITY",
                    )
                encoded = self._payload_bytes(tx.payload)
                if (
                    self._pending_bytes + len(encoded)
                    > self.max_pending_bytes
                ):
                    return dict(
                        status="busy",
                        reason="PENDING_BYTE_CAPACITY",
                    )
                if (
                    len(self._ledger) + len(self._pending)
                    >= self.max_records
                ):
                    return dict(
                        status="held",
                        reason="LEDGER_CAPACITY",
                    )
                self._register_session(tx.session_id)
            except QuarantineError as exc:
                return dict(
                    status="quarantined", reason=str(exc)
                )
            except HoldError as exc:
                return dict(status="held", reason=str(exc))
            except (
                ValueError,
                TypeError,
                UnicodeError,
            ) as exc:
                return dict(
                    status="rejected", reason=str(exc)
                )
            token = uuid.uuid4().hex
            self._pending[token] = (
                asyncio.get_running_loop().create_future()
            )
            self._pending_bytes += len(encoded)
            deadline = (
                asyncio.get_running_loop().time()
                + self.transaction_timeout
            )
            self.queue.put_nowait(
                (token, tx, encoded, deadline)
            )
            self._event(
                "QUEUED",
                tx.session_id,
                tx.sequence_number,
                "Awaiting verification",
            )
            return dict(
                status="pending", tracking_token=token
            )

        @staticmethod
        def _receipt(token, result):
            status, value = result
            receipt = dict(
                status=status, tracking_token=token
            )
            if isinstance(value, LedgerRecord):
                receipt.update(
                    {
                        name: getattr(value, name)
                        for name in LedgerRecord.__dataclass_fields__
                    }
                )
            else:
                receipt["reason"] = value
            return receipt

        def _complete(self, token, status, value, size):
            future = self._pending.pop(token, None)
            if future is None:
                return
            self._pending_bytes -= size
            result = (status, value)
            self._completed[token] = result
            while (
                len(self._completed) > self.receipt_capacity
            ):
                self._completed.popitem(last=False)
            if not future.done():
                future.set_result(result)

        def governance_get_status(self, tracking_token):
            if tracking_token in self._pending:
                return dict(
                    status="pending",
                    tracking_token=tracking_token,
                )
            result = self._completed.get(tracking_token)
            return (
                self._receipt(tracking_token, result)
                if result
                else dict(
                    status="unknown",
                    reason="Unknown or evicted receipt; no trust granted",
                )
            )

        async def wait(self, tracking_token, timeout=None):
            future = self._pending.get(tracking_token)
            if future is None:
                return self.governance_get_status(
                    tracking_token
                )
            try:
                result = await asyncio.wait_for(
                    asyncio.shield(future),
                    self.wait_timeout
                    if timeout is None
                    else timeout,
                )
            except TimeoutError:
                return dict(
                    status="pending",
                    tracking_token=tracking_token,
                    reason="RECEIPT_TIMEOUT",
                )
            return self._receipt(tracking_token, result)

    """Supervised verification worker with deadlines and cooperative scheduling."""
    import asyncio
    import hashlib
    import hmac
    import time

    class WorkerLifecycle:
        async def start(self):
            if self._closed or self._held_reason:
                raise HoldError("Engine is closed or held")
            if self._worker is None:
                self._worker = asyncio.create_task(
                    self.run_background_governance_loop()
                )
                self._worker.add_done_callback(
                    self._worker_stopped
                )
            return self

        async def close(self):
            self._closed = True
            if self._shutdown_task is None:
                self._shutdown_task = asyncio.create_task(
                    self._shutdown()
                )
            # A cancelled caller cannot abandon cleanup or cancel other closers.
            await asyncio.shield(self._shutdown_task)

        async def _shutdown(self):
            worker = self._worker
            if worker is None:
                return
            try:
                await asyncio.wait_for(
                    self.queue.join(), self.shutdown_timeout
                )
            except TimeoutError:
                self._hold("SHUTDOWN_TIMEOUT")
            finally:
                worker.cancel()
                try:
                    await worker
                except asyncio.CancelledError:
                    pass
                self._worker_stopped(worker)
                self._worker = None

        def _worker_stopped(self, task):
            if (
                not self._closed
                and self._held_reason is None
            ):
                self._hold("WORKER_STOPPED")
            if not task.cancelled():
                task.exception()  # Retrieve failure; terminal receipts carry HOLD.
            while not self.queue.empty():
                token, tx, encoded, deadline = (
                    self.queue.get_nowait()
                )
                self._complete(
                    token,
                    "held",
                    self._held_reason or "WORKER_STOPPED",
                    len(encoded),
                )
                self.queue.task_done()
            for token in tuple(self._pending):
                self._complete(
                    token,
                    "held",
                    self._held_reason or "WORKER_STOPPED",
                    0,
                )

        @staticmethod
        def _hash_frame(tx, encoded):
            payload_hash = hashlib.sha256(
                encoded
            ).hexdigest()
            block_hash = sha256_text(
                canonical_json(
                    block_material(tx, payload_hash)
                )
            )
            return payload_hash, block_hash

        async def _compute(
            self, function, encoded, *prefix
        ):
            if len(encoded) < self.hash_offload_bytes:
                self._inline_jobs += 1
                return function(*prefix, encoded)
            self._thread_jobs += 1
            try:
                return await asyncio.wait_for(
                    asyncio.to_thread(
                        function, *prefix, encoded
                    ),
                    self.hash_timeout,
                )
            except TimeoutError as exc:
                self._hold("HASH_TIMEOUT")
                raise HoldError("HASH_TIMEOUT") from exc

        async def _process(self, tx, encoded, deadline):
            self._check_session(tx.session_id)
            if (
                asyncio.get_running_loop().time()
                >= deadline
            ):
                raise HoldError("TRANSACTION_DEADLINE")
            seq, parent = self.head(tx.session_id)
            if tx.sequence_number != seq + 1:
                raise QuarantineError(
                    f"Expected sequence {seq + 1}; received {tx.sequence_number}"
                )
            if not hmac.compare_digest(
                tx.previous_hash, parent
            ):
                raise QuarantineError(
                    "Predecessor does not match the verified session head"
                )
            payload_hash, block_hash = await self._compute(
                self._hash_frame, encoded, tx
            )
            if (
                tx.expected_hash is not None
                and not hmac.compare_digest(
                    payload_hash, tx.expected_hash
                )
            ):
                raise QuarantineError(
                    "Payload SHA-256 assertion mismatch"
                )
            self._check_session(
                tx.session_id
            )  # Quarantine may arrive during thread work.
            if (
                asyncio.get_running_loop().time()
                >= deadline
            ):
                raise HoldError("TRANSACTION_DEADLINE")
            record = LedgerRecord(
                tx.session_id,
                tx.sequence_number,
                tx.source_agent,
                tx.target_entity,
                payload_hash,
                tx.previous_hash,
                block_hash,
                time.time_ns(),
            )
            self._ledger[
                (tx.session_id, tx.sequence_number)
            ] = record
            self._heads[tx.session_id] = (
                tx.sequence_number,
                block_hash,
            )
            self._payload_hashes.add(payload_hash)
            self._event(
                "COMMITTED",
                tx.session_id,
                tx.sequence_number,
                block_hash,
            )
            return record

        async def run_background_governance_loop(self):
            processed = 0
            while True:
                (
                    token,
                    tx,
                    encoded,
                    deadline,
                ) = await self.queue.get()
                try:
                    record = await self._process(
                        tx, encoded, deadline
                    )
                    self._complete(
                        token,
                        "verified",
                        record,
                        len(encoded),
                    )
                except QuarantineError as exc:
                    self.quarantine(
                        tx.session_id,
                        tx.sequence_number,
                        str(exc),
                    )
                    self._complete(
                        token,
                        "quarantined",
                        str(exc),
                        len(encoded),
                    )
                except HoldError as exc:
                    self.hold_session(
                        tx.session_id, str(exc)
                    )
                    self._complete(
                        token,
                        "held",
                        str(exc),
                        len(encoded),
                    )
                except asyncio.CancelledError:
                    self._complete(
                        token,
                        "held",
                        "WORKER_CANCELLED",
                        len(encoded),
                    )
                    raise
                except Exception as exc:
                    self._hold(
                        "WORKER_ERROR:" + type(exc).__name__
                    )
                    self._complete(
                        token,
                        "held",
                        self._held_reason,
                        len(encoded),
                    )
                finally:
                    self.queue.task_done()
                    # Do not retain the last payload while waiting on an empty queue.
                    del tx, encoded
                processed += 1
                if processed % self.yield_every == 0:
                    await asyncio.sleep(0)

    """Registered payload checks and envelope lineage verification."""
    import hashlib
    import hmac

    class VerificationBoundary:
        def _verifier_available(self):
            if self._held_reason:
                raise HoldError(self._held_reason)
            if (
                self._closed
                or self._worker is None
                or self._worker.done()
            ):
                raise HoldError("VERIFIER_UNAVAILABLE")

        async def governance_verify_payload(
            self, payload, expected_hash
        ):
            if not self._valid_hash(expected_hash):
                return dict(
                    verified=False,
                    registered=False,
                    reason="Malformed digest",
                )
            try:
                self._verifier_available()
                if (
                    self._verification_jobs
                    >= self.verification_capacity
                ):
                    raise HoldError("VERIFICATION_CAPACITY")
                encoded = self._payload_bytes(payload)
                if (
                    self._verification_bytes + len(encoded)
                    > self.max_verification_bytes
                ):
                    raise HoldError(
                        "VERIFICATION_BYTE_CAPACITY"
                    )
                self._verification_jobs += 1
                self._verification_bytes += len(encoded)
                try:
                    actual = await self._compute(
                        lambda data: hashlib.sha256(
                            data
                        ).hexdigest(),
                        encoded,
                    )
                    self._verifier_available()  # Availability may change across await.
                finally:
                    self._verification_jobs -= 1
                    self._verification_bytes -= len(encoded)
            except HoldError as exc:
                return dict(
                    verified=False,
                    registered=False,
                    disposition="held",
                    reason=str(exc),
                )
            except (ValueError, UnicodeError) as exc:
                return dict(
                    verified=False,
                    registered=False,
                    reason=str(exc),
                )
            except Exception as exc:
                self._hold(
                    "VERIFIER_ERROR:" + type(exc).__name__
                )
                return dict(
                    verified=False,
                    registered=False,
                    disposition="held",
                    reason=self._held_reason,
                )
            registered = (
                expected_hash in self._payload_hashes
            )
            matches = hmac.compare_digest(
                actual, expected_hash
            )
            return dict(
                verified=registered and matches,
                registered=registered,
                actual_hash=actual,
                expected_hash=expected_hash,
                reason="Verified against committed content"
                if registered and matches
                else "Digest mismatch"
                if not matches
                else "Digest is not in this ledger",
            )

        async def verify_envelope(self, envelope):
            tx = self._parse(envelope["transaction"])
            self._check_session(tx.session_id)
            record = self._ledger.get(
                (tx.session_id, tx.sequence_number)
            )
            supplied_block = envelope.get("ledger_hash", "")
            if (
                record is None
                or not self._valid_hash(supplied_block)
                or not hmac.compare_digest(
                    record.block_hash, supplied_block
                )
                or block_material(tx, record.payload_hash)
                != block_material(
                    record, record.payload_hash
                )
            ):
                self.quarantine(
                    tx.session_id,
                    tx.sequence_number,
                    "Envelope lineage mismatch",
                )
                raise QuarantineError(
                    "Incoming envelope failed lineage verification"
                )
            result = await self.governance_verify_payload(
                tx.payload, envelope.get("payload_hash", "")
            )
            self._check_session(tx.session_id)
            if result.get("disposition") == "held":
                raise HoldError(result["reason"])
            if not result[
                "verified"
            ] or record.payload_hash != result.get(
                "actual_hash"
            ):
                self.quarantine(
                    tx.session_id,
                    tx.sequence_number,
                    "Payload mismatch",
                )
                raise QuarantineError(
                    "Incoming envelope failed payload verification"
                )
            return record

    """Per-session outbound serialization and immutable input snapshots."""
    import asyncio

    class AgentGateway:
        """Snapshot mutable inputs, serialize outbound chains, gate every invocation."""

        def __init__(
            self,
            engine,
            session_id,
            agent_id="primary-agent",
            max_context_entries=64,
        ):
            if (
                type(max_context_entries) is not int
                or max_context_entries < 1
            ):
                raise ValueError(
                    "max_context_entries must be positive"
                )
            self.engine, self.session_id, self.agent_id = (
                engine,
                session_id,
                agent_id,
            )
            self.max_context_entries = max_context_entries
            self.context = []

        async def wrap_output(
            self, payload, target_entity="tool-boundary"
        ):
            async with self.engine.session_lock(
                self.session_id
            ):
                seq, parent = self.engine.head(
                    self.session_id
                )
                frame = dict(
                    session_id=self.session_id,
                    sequence_number=seq + 1,
                    source_agent=self.agent_id,
                    target_entity=target_entity,
                    payload=payload,
                    previous_hash=parent,
                )
                receipt = await self.engine.governance_commit_state(
                    **frame
                )
                if receipt["status"] != "pending":
                    self.context.clear()
                    error = (
                        QuarantineError
                        if receipt["status"]
                        == "quarantined"
                        else HoldError
                    )
                    raise error(
                        receipt.get(
                            "reason", receipt["status"]
                        )
                    )
                try:
                    committed = await self.engine.wait(
                        receipt["tracking_token"]
                    )
                except asyncio.CancelledError:
                    self.context.clear()
                    self.engine.hold_session(
                        self.session_id,
                        "OUTBOUND_CANCELLED",
                    )
                    raise
                if committed["status"] != "verified":
                    self.context.clear()
                    if committed["status"] == "pending":
                        self.engine.hold_session(
                            self.session_id,
                            "RECEIPT_TIMEOUT",
                        )
                    error = (
                        QuarantineError
                        if committed["status"]
                        == "quarantined"
                        else HoldError
                    )
                    raise error(
                        committed.get(
                            "reason", "Commit unavailable"
                        )
                    )
                return dict(
                    transaction=frame,
                    payload_hash=committed["payload_hash"],
                    ledger_hash=committed["block_hash"],
                )

        async def execute_verified(self, envelope, tool):
            try:
                # Only immutable strings and validated scalar metadata survive this
                # snapshot. Later caller mutation cannot swap the verified payload.
                snapshot = dict(
                    transaction=dict(
                        envelope["transaction"]
                    ),
                    payload_hash=envelope["payload_hash"],
                    ledger_hash=envelope["ledger_hash"],
                )
                transaction = self.engine._parse(
                    snapshot["transaction"]
                )
                if (
                    transaction.session_id
                    != self.session_id
                    or transaction.target_entity
                    != self.agent_id
                ):
                    raise QuarantineError(
                        "Unexpected session or recipient"
                    )
                await self.engine.verify_envelope(snapshot)
            except asyncio.CancelledError:
                self.context.clear()
                self.engine.hold_session(
                    self.session_id,
                    "VERIFICATION_CANCELLED",
                )
                raise
            except HoldError:
                self.context.clear()
                raise
            except (
                GovernanceError,
                KeyError,
                TypeError,
                ValueError,
            ) as exc:
                self.context.clear()
                self.engine.quarantine(
                    self.session_id,
                    -1,
                    f"Hash/chain hook halted ingestion: {exc}",
                )
                raise QuarantineError(
                    "Context cleared; tool execution halted"
                ) from exc
            self.context.append(snapshot["ledger_hash"])
            del self.context[: -self.max_context_entries]
            return tool(transaction.payload)

    """A bounded scan/sequence pipeline; presentation need not retain the whole stream."""
    import asyncio
    from base64 import b64encode
    from inspect import isawaitable

    def chunk_payload(chunk):
        return canonical_json(
            dict(
                encoding="base64",
                chunk_index=chunk.index,
                start_byte=chunk.start,
                end_byte=chunk.end,
                data=b64encode(chunk.data).decode("ascii"),
            )
        )

    class StreamPump:
        """Own the staging queue, source lifetime, and one sequencer."""

        def __init__(
            self,
            packets,
            engine,
            session_id,
            on_verified,
            cdc_parameters,
            staging_size,
            max_packet_bytes,
            target_entity,
        ):
            self.packets, self.on_verified = (
                packets,
                on_verified,
            )
            self.scanner = RabinCDCScanner(
                **(cdc_parameters or {})
            )
            self.staging = asyncio.Queue(
                maxsize=staging_size
            )
            self.counters = dict(
                chunks=0, input_bytes=0, staging_peak=0
            )
            self.sender = AgentGateway(
                engine, session_id, "stream-agent"
            )
            self.max_packet_bytes, self.target_entity = (
                max_packet_bytes,
                target_entity,
            )

        async def push(self, chunk):
            await self.staging.put(chunk)
            self.counters["staging_peak"] = max(
                self.counters["staging_peak"],
                self.staging.qsize(),
            )

        async def produce(self):
            try:
                async for packet in self.packets:
                    if (
                        memoryview(packet).nbytes
                        > self.max_packet_bytes
                    ):
                        raise ValueError(
                            "PACKET_BYTE_CAPACITY"
                        )
                    self.counters["input_bytes"] += (
                        memoryview(packet).nbytes
                    )
                    for chunk in self.scanner.feed(packet):
                        await self.push(chunk)
                    await asyncio.sleep(0)
                for chunk in self.scanner.finish():
                    await self.push(chunk)
                await self.staging.put(None)
            finally:
                close = getattr(
                    self.packets, "aclose", None
                )
                if close is not None:
                    await close()

        async def consume(self):
            while True:
                chunk = await self.staging.get()
                try:
                    if chunk is None:
                        return
                    envelope = (
                        await self.sender.wrap_output(
                            chunk_payload(chunk),
                            self.target_entity,
                        )
                    )
                    result = self.on_verified(envelope)
                    if isawaitable(result):
                        await result
                    self.counters["chunks"] += 1
                finally:
                    self.staging.task_done()

    async def stream_to_ledger(
        packets,
        engine,
        session_id,
        on_verified,
        *,
        cdc_parameters=None,
        staging_size=8,
        max_packet_bytes=65536,
        deadline_s=30.0,
        target_entity="tool-boundary",
    ):
        """Scan packets concurrently with sequential commits and bounded staging.

        on_verified receives a committed envelope; recipients still verify before
        invoking tools. No retries are owned here. The source's aclose() is called
        on all exits. A failure cancels siblings; the borrowed engine is caller-owned.
        The pipeline retains no whole stream. CPU scanning yields between packets.
        """
        if (
            type(staging_size) is not int
            or staging_size < 1
        ):
            raise ValueError(
                "staging_size must be positive"
            )
        if (
            type(max_packet_bytes) is not int
            or max_packet_bytes < 1
        ):
            raise ValueError(
                "max_packet_bytes must be positive"
            )
        if type(deadline_s) not in (
            float,
            int,
        ) or not 0 < deadline_s < float("inf"):
            raise ValueError(
                "deadline_s must be finite and positive"
            )
        pump = StreamPump(
            packets,
            engine,
            session_id,
            on_verified,
            cdc_parameters,
            staging_size,
            max_packet_bytes,
            target_entity,
        )
        async with asyncio.timeout(deadline_s):
            async with asyncio.TaskGroup() as group:
                group.create_task(
                    pump.produce(), name="cdc-producer"
                )
                group.create_task(
                    pump.consume(), name="ledger-sequencer"
                )
        return pump.counters

    """Public facade for the bounded streaming-governance reference implementation."""
    import asyncio as asyncio
    import hashlib as hashlib
    import time as time
    from dataclasses import asdict as asdict

    class GovernanceLedgerEngine(
        EngineState,
        ReceiptFlow,
        WorkerLifecycle,
        VerificationBoundary,
    ):
        """Compose bounded state, admission, worker lifecycle, and verification seams.

        Small digests run inline; large hashes use one supervised thread job.
        Pending receipts grant no trust. Authoritative records never evict.
        """

    return (
        AgentGateway,
        GovernanceLedgerEngine,
        HoldError,
        QuarantineError,
        RabinCDCScanner,
        asdict,
        asyncio,
        canonical_json,
        hashlib,
        json,
        sha256_text,
        stream_to_ledger,
        time,
    )


@app.cell(hide_code=True)
def scenario_runner(
    AgentGateway,
    GovernanceLedgerEngine,
    HoldError,
    QuarantineError,
    asdict,
    asyncio,
    canonical_json,
    sha256_text,
):
    """Reactive notebook scenario runner; each execution uses a fresh engine."""
    import base64
    import copy

    async def simulate_governance(chunks, scenario):
        engine = GovernanceLedgerEngine(queue_size=8)
        receiver = AgentGateway(
            engine, "demo-session", "tool-boundary"
        )
        trace = []
        calls = []
        envelopes = []
        attack_at = min(2, max(0, len(chunks) - 1))
        if scenario == "Expired transaction (injected)":
            _normal_process = engine._process

            async def _expired_for_tracer(
                tx, encoded, deadline
            ):
                # EXPIRED_FOR_TRACER: deterministic deadline-failure injection.
                if tx.sequence_number == attack_at:
                    deadline = (
                        asyncio.get_running_loop().time()
                        - 1
                    )
                return await _normal_process(
                    tx, encoded, deadline
                )

            engine._process = _expired_for_tracer
        await engine.start()
        try:
            for chunk in chunks:
                seq, parent = engine.head("demo-session")
                payload = canonical_json(
                    dict(
                        encoding="base64",
                        chunk_index=chunk.index,
                        start_byte=chunk.start,
                        end_byte=chunk.end,
                        data=base64.b64encode(
                            chunk.data
                        ).decode("ascii"),
                    )
                )
                frame = dict(
                    session_id="demo-session",
                    sequence_number=seq + 1,
                    source_agent="stream-agent",
                    target_entity="tool-boundary",
                    payload=payload,
                    previous_hash=parent,
                )
                attacking = chunk.index == attack_at
                if (
                    attacking
                    and scenario == "Broken predecessor"
                ):
                    frame["previous_hash"] = "f" * 64
                if (
                    attacking
                    and scenario == "Missing sequence"
                ):
                    frame["sequence_number"] += 1
                if (
                    attacking
                    and scenario
                    == "Payload changed before commit"
                ):
                    frame["expected_hash"] = sha256_text(
                        payload
                    )
                    frame["payload"] += " altered"
                receipt = (
                    await engine.governance_commit_state(
                        **frame
                    )
                )
                trace.append(
                    dict(
                        stage="queue admission",
                        chunk=chunk.index,
                        sequence=frame["sequence_number"],
                        status=receipt["status"],
                        detail="Producer received a pending token; no trust granted",
                    )
                )
                if receipt["status"] != "pending":
                    break
                result = await engine.wait(
                    receipt["tracking_token"]
                )
                trace.append(
                    dict(
                        stage="SHA-256 worker",
                        chunk=chunk.index,
                        sequence=frame["sequence_number"],
                        status=result["status"],
                        detail=result.get(
                            "reason",
                            result.get("block_hash", ""),
                        ),
                    )
                )
                if result["status"] != "verified":
                    receiver.context.clear()
                    break
                envelope = dict(
                    transaction=frame,
                    payload_hash=result["payload_hash"],
                    ledger_hash=result["block_hash"],
                )
                envelopes.append(copy.deepcopy(envelope))
                if (
                    attacking
                    and scenario == "Replay sequence"
                ):
                    replay = await engine.governance_commit_state(
                        **frame
                    )
                    replay_result = await engine.wait(
                        replay["tracking_token"]
                    )
                    trace.append(
                        dict(
                            stage="replayed transaction",
                            chunk=chunk.index,
                            sequence=frame[
                                "sequence_number"
                            ],
                            status=replay_result["status"],
                            detail=replay_result.get(
                                "reason", ""
                            ),
                        )
                    )
                if (
                    attacking
                    and scenario
                    == "Payload changed in handoff"
                ):
                    envelope["transaction"]["payload"] += (
                        " injected instruction"
                    )
                if (
                    attacking
                    and scenario
                    == "Routing metadata rewritten"
                ):
                    envelope["transaction"][
                        "source_agent"
                    ] = "untrusted-agent"
                if (
                    attacking
                    and scenario
                    == "Verifier unavailable (injected)"
                ):
                    engine.hold_session(
                        "demo-session",
                        "VERIFIER_UNAVAILABLE_INJECTED",
                    )
                try:
                    await receiver.execute_verified(
                        envelope,
                        lambda text, index=chunk.index: (
                            calls.append(index)
                        ),
                    )
                    trace.append(
                        dict(
                            stage="tool boundary",
                            chunk=chunk.index,
                            sequence=frame[
                                "sequence_number"
                            ],
                            status="executed",
                            detail="Payload and lineage verified before tool invocation",
                        )
                    )
                except (QuarantineError, HoldError) as exc:
                    trace.append(
                        dict(
                            stage="tool boundary",
                            chunk=chunk.index,
                            sequence=frame[
                                "sequence_number"
                            ],
                            status="HALTED",
                            detail=str(exc),
                        )
                    )
                    break
            return dict(
                records=[
                    asdict(record)
                    for record in engine.ledger.values()
                ],
                events=[
                    dict(event) for event in engine.events
                ],
                trace=trace,
                calls=calls,
                envelopes=envelopes,
                context=list(receiver.context),
                quarantined=bool(engine._quarantined),
                queue_drained=engine.queue.empty(),
                health=engine.health(),
            )
        finally:
            await engine.close()

    return base64, simulate_governance


@app.cell(hide_code=True)
def stream_controls(canonical_json, mo, sha256_text):
    _sample_lines = []
    for _i in range(48):
        _action = [
            "plan",
            "retrieve",
            "tool_result",
            "handoff",
            "verify",
            "summarize",
        ][_i % 6]
        _sample_lines.append(
            canonical_json(
                dict(
                    timestamp=f"2026-10-16T09:{_i:02d}:00Z",
                    agent=f"agent-{_i % 3}",
                    event=_action,
                    trace=sha256_text(f"event-{_i}")[:18],
                    message=f"Step {_i}: evidence {_i * 17} · café / 東京 / 🧬; preserve exact bytes.",
                )
            )
        )
    source_ui = mo.ui.text_area(
        value="\n".join(_sample_lines),
        label="Raw UTF-8 stream",
        full_width=True,
        rows=7,
        max_length=100000,
    )
    nominal_ui = mo.ui.dropdown(
        options={
            "128 bytes": 128,
            "256 bytes": 256,
            "512 bytes": 512,
            "1 KiB": 1024,
            "4 KiB": 4096,
        },
        value="512 bytes",
        label="Nominal boundary interval",
    )
    window_ui = mo.ui.dropdown(
        options={
            "16 bytes": 16,
            "32 bytes": 32,
            "64 bytes": 64,
        },
        value="64 bytes",
        label="Rolling window",
    )
    packet_ui = mo.ui.slider(
        start=1,
        stop=1024,
        value=73,
        step=1,
        label="Transport packet bytes",
        show_value=True,
    )
    scenario_ui = mo.ui.dropdown(
        options=[
            "Clean stream",
            "Payload changed before commit",
            "Payload changed in handoff",
            "Broken predecessor",
            "Missing sequence",
            "Replay sequence",
            "Routing metadata rewritten",
            "Expired transaction (injected)",
            "Verifier unavailable (injected)",
        ],
        value="Clean stream",
        label="Governance scenario",
        full_width=True,
    )
    mo.vstack(
        [
            mo.md(
                "## 01 / Configure the stream\nEdit the stream or vary its transport packet size. Transport boundaries must never change CDC chunk boundaries."
            ),
            source_ui,
            mo.hstack(
                [nominal_ui, window_ui, packet_ui],
                widths="equal",
            ),
            scenario_ui,
        ]
    )
    return nominal_ui, packet_ui, scenario_ui, source_ui, window_ui


@app.cell(hide_code=True)
def scan_stream(
    RabinCDCScanner,
    mo,
    nominal_ui,
    packet_ui,
    source_ui,
    time,
    window_ui,
):
    raw_bytes = source_ui.value.encode("utf-8")
    cdc_parameters = dict(
        block_size_target=nominal_ui.value,
        window_size=window_ui.value,
    )
    _scanner = RabinCDCScanner(**cdc_parameters)
    _started = time.perf_counter()
    chunks = []
    _packet_view = memoryview(raw_bytes)
    for _offset in range(
        0, len(raw_bytes), packet_ui.value
    ):
        chunks.extend(
            _scanner.feed(
                _packet_view[
                    _offset : _offset + packet_ui.value
                ]
            )
        )
    chunks.extend(_scanner.finish())
    scan_ms = (time.perf_counter() - _started) * 1000
    assert b"".join(_c.data for _c in chunks) == raw_bytes
    mo.Html(f"""<div class="gov-metrics">
    <div class="gov-metric"><b>{len(raw_bytes):,}</b><small>INPUT BYTES</small></div>
    <div class="gov-metric"><b>{len(chunks)}</b><small>DETERMINISTIC CHUNKS</small></div>
    <div class="gov-metric"><b>{len(raw_bytes) / max(1, len(chunks)):.0f} B</b><small>OBSERVED MEAN</small></div>
    <div class="gov-metric"><b>{scan_ms:.2f} ms</b><small>THIS SCAN · NOT A BENCHMARK</small></div></div>""")
    return chunks, raw_bytes


@app.cell(hide_code=True)
def chunk_visual(chunks, mo, nominal_ui, raw_bytes, window_ui):
    _palette = {
        "content": "#38bfa0",
        "max size": "#ebae59",
        "tail": "#6d9fdf",
    }
    _rects = []
    for _chunk in chunks:
        _x = (
            12 + _chunk.start / max(1, len(raw_bytes)) * 936
        )
        _w = (
            (_chunk.end - _chunk.start)
            / max(1, len(raw_bytes))
            * 936
        )
        _title = f"Chunk {_chunk.index} · [{_chunk.start}, {_chunk.end}) · {_chunk.reason} · {_chunk.end - _chunk.start} bytes"
        _rects.append(
            f'<rect x="{_x:.2f}" y="35" width="{max(0.5, _w - 1):.2f}" height="48" rx="3" fill="{_palette[_chunk.reason]}"><title>{_title}</title></rect>'
        )
    mo.vstack(
        [
            mo.md(
                "## 02 / Inspect content boundaries\nGreen = content cut · amber = maximum size · blue = final tail. Hover for byte offsets."
            ),
            mo.Html(
                '<svg viewBox="0 0 960 114" role="img" aria-label="Content-defined chunk byte map" style="width:100%;background:#102633;border-radius:12px"><text x="12" y="21" fill="#b4ccda" font-size="11" font-family="monospace">BYTE OFFSET 0</text>'
                + "".join(_rects)
                + f'<text x="948" y="104" text-anchor="end" fill="#b4ccda" font-size="11" font-family="monospace">{len(raw_bytes):,} BYTES</text></svg>'
            ),
            mo.md(
                f"Minimum **{max(window_ui.value, nominal_ui.value // 4)} B** · maximum **{nominal_ui.value * 4} B** · boundary condition `fingerprint % {nominal_ui.value} == 1`. The window continues across chunk cuts."
            ),
        ]
    )
    return


