@app.cell(hide_code=True)
def chunk_detail(chunk_picker, chunks, hashlib, mo):
    if chunks:
        _selected = chunks[
            min(chunk_picker.value, len(chunks) - 1)
        ]
        mo.output.replace(
            mo.vstack(
                [
                    mo.md(
                        f"**Chunk {_selected.index}** · bytes `[{_selected.start}, {_selected.end})` · cut: `{_selected.reason}` · fingerprint `{_selected.fingerprint}`"
                    ),
                    mo.ui.tabs(
                        {
                            "Byte digest": mo.md(
                                f"`SHA256(raw chunk bytes) = {hashlib.sha256(_selected.data).hexdigest()}`\n\nThis address differs from the ledger payload hash, which hashes a canonical JSON envelope carrying these bytes in base64."
                            ),
                            "UTF-8 preview": mo.plain_text(
                                _selected.data[
                                    :1000
                                ].decode(
                                    "utf-8",
                                    errors="replace",
                                )
                                + (
                                    "…"
                                    if len(_selected.data)
                                    > 1000
                                    else ""
                                )
                            ),
                            "Hex bytes": mo.plain_text(
                                _selected.data[:192].hex(
                                    " "
                                )
                            ),
                        }
                    ),
                    mo.md(
                        "Preview uses replacement characters if a chunk cuts through a code point. Stored bytes remain exact; join bytes before decoding."
                    ),
                ]
            )
        )
    else:
        mo.output.replace(
            mo.md(
                "Empty stream: no chunks, no transactions."
            )
        )
    return


