@app.cell(hide_code=True)
def vv_controls(artifact_files, json, mo):
    import gzip
    import sqlite3

    vv_connection = sqlite3.connect(":memory:")
    vv_connection.deserialize(
        artifact_files["vv_evidence/assurance.sqlite"]
    )
    vv_connection.row_factory = sqlite3.Row
    _vv_cursor = vv_connection.execute(
        "PRAGMA query_only=ON"
    )
    vv_summary = json.loads(
        artifact_files["vv_evidence/summary.json"]
    )
    finding_scope = mo.ui.dropdown(
        options={
            "Applicable obligations": "applicable",
            "All tuples": "all",
            "Out of scope": "scope",
        },
        value="Applicable obligations",
        label="Finding scope",
    )
    finding_invariant = mo.ui.dropdown(
        options={
            "All invariants": "all",
            **{
                _row["id"]: _row["id"]
                for _row in vv_connection.execute(
                    "SELECT id FROM invariants ORDER BY id"
                )
            },
        },
        value="All invariants",
        label="Invariant",
    )
    mo.vstack(
        [
            mo.md(
                "## 09 / SQL assurance browser\n**7,488 tuples = 18 invariants × 32 challenges × 13 gates.** The 32 declared obligations are satisfied by both assertion frameworks. Other tuples retain OUT_OF_SCOPE reasons and are not passes. Every tuple links to both behavioral-contract assertions or clearly labeled catalog-scope audits. This finite catalog does not cover all inputs, schedules, threats or simultaneous faults."
            ),
            mo.hstack(
                [finding_scope, finding_invariant],
                justify="start",
            ),
            mo.hstack(
                [
                    mo.download(
                        gzip.compress(artifact_files[
                            "vv_evidence/assurance.sqlite"
                        ], mtime=0),
                        filename='assurance.sqlite.gz',
                        label='SQLite database · gzip',
                    ),
                    mo.download(
                        gzip.compress(artifact_files[
                            "vv_evidence/assurance.sql"
                        ], mtime=0),
                        filename='assurance.sql.gz',
                        label='Replayable SQL · gzip',
                    ),
                    mo.download(
                        gzip.compress(artifact_files[
                            "vv_evidence/dataframes/cross_report.csv"
                        ], mtime=0),
                        filename='cross_report.csv.gz',
                        label='All possibilities · CSV · gzip'
                    ),
                    mo.download(
                        gzip.compress(artifact_files[
                            "vv_evidence/dataframes/finding_evidence.csv"
                        ], mtime=0),
                        filename='finding_evidence.csv.gz',
                        label='Finding ↔ test links · gzip'                    ),
                ],
                justify="start",
                gap=1,
            ),
        ]
    )
    return finding_invariant, finding_scope, vv_connection


@app.cell(hide_code=True)
def vv_findings(
    artifact_files,
    finding_invariant,
    finding_scope,
    json,
    mo,
    vv_connection,
):
    _parameters = dict(
        scope=finding_scope.value,
        invariant=finding_invariant.value,
    )
    _where = """WHERE (:invariant='all' OR invariant_id=:invariant) AND
    (:scope='all' OR (:scope='applicable' AND obligation_id IS NOT NULL) OR (:scope='scope' AND obligation_id IS NULL))"""
    _vv_count = vv_connection.execute(
        "SELECT COUNT(*) FROM cross_report " + _where,
        _parameters,
    ).fetchone()[0]
    _vv_rows = [
        dict(_row)
        for _row in vv_connection.execute(
            "SELECT id,requirement_id,invariant_id,failure_id,gate_id,obligation_id,disposition,scope_reason FROM cross_report "
            + _where
            + " ORDER BY id LIMIT 100",
            _parameters,
        )
    ]
    _vv_requirements = [
        dict(_row)
        for _row in vv_connection.execute(
            "SELECT requirement_id,assertion_id,obligation_id,framework,run_id,status,historical,evidence_path FROM requirement_evidence ORDER BY requirement_id,assertion_id"
        )
    ]
    _vv_supersessions = [
        dict(_row)
        for _row in vv_connection.execute(
            "SELECT * FROM supersessions ORDER BY failed_assertion_id"
        )
    ]
    _vv_mutation_gap = [
        dict(_row)
        for _row in vv_connection.execute(
            "SELECT * FROM mutation_supersessions"
        )
    ]
    mo.vstack(
        [
            mo.md(
                f"Showing **{len(_vv_rows)} of {_vv_count:,}** matching rows (display cap 100). Download the complete datasets above. Current campaign: **126 passing test executions**; six historical failures remain in the evidence."
            ),
            mo.ui.tabs(
                {
                    "Findings": mo.ui.table(
                        _vv_rows,
                        selection=None,
                        page_size=10,
                    ),
                    "Requirement assertions": mo.ui.table(
                        _vv_requirements,
                        selection=None,
                        page_size=10,
                    ),
                    "Fixed regressions": mo.ui.table(
                        _vv_supersessions,
                        selection=None,
                        page_size=6,
                    ),
                    "Stronger mutation assertion": mo.ui.table(
                        _vv_mutation_gap, selection=None
                    ),
                    "Local speed & memory": mo.json(
                        json.loads(
                            artifact_files[
                                "vv_evidence/observations_pytest/C031.json"
                            ]
                        )
                    ),
                }
            ),
            mo.md(
                "A passing run of the same unchanged regression assertion supersedes its failing run. The initial M023 survivor is linked to a stronger deadline assertion that requires HOLD without quarantine; the earlier test is retained. Runtime statement/branch coverage is 96.15% for in-process modules. The MCP subprocess is exercised through separate real wire tests."
            ),
        ]
    )
    return


